{
  "scope_issues": [
    "The policy applies to donations from individuals, but does not specify whether non-individual donations (e.g., corporate) or other types of donations are covered."
  ],
  "statuses": [
    {
      "evidence_quote": "You must be recognised as a charity or CASC for tax purposes.",
      "id": "a1",
      "justification": "The customer scenario states they run a small, independent charity, which implies recognition as a charity for tax purposes; this directly supports the proposition.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "",
      "id": "a2",
      "justification": "The donor's tax document covers the year ending 5 April 2024, not the tax year of the donation (2026), and no current-year donor tax evidence is available. The scenario does not establish whether the donor paid at least as much in tax as the claimed Gift Aid. Therefore, the tax requirement is not established.",
      "status": "UNKNOWN"
    },
    {
      "evidence_quote": "A scanned declaration from an earlier event is incomplete: the page stating its coverage and duration is missing.",
      "id": "a3",
      "justification": "The Gift Aid declaration is incomplete, and there is no evidence that it covers the current donation or is valid for the relevant tax year. The incompleteness negates the presence of a valid declaration.",
      "status": "FALSE"
    },
    {
      "evidence_quote": "The transfer was unrelated to sales, bookings, benefits, payroll deductions, shares or the separately settled charity-card and voucher payments.",
      "id": "a4",
      "justification": "The donation was made from a personal bank account and is not linked to payroll giving, so it satisfies the condition that it is not made through Payroll Giving.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "The transfer was unrelated to sales, bookings, benefits, payroll deductions, shares or the separately settled charity-card and voucher payments.",
      "id": "a5",
      "justification": "The donation is described as an emergency vet appeal, not a payment for goods or services, and the charity did not buy goods or services for this donation. Thus, it is not a payment for goods or services.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "",
      "id": "a6",
      "justification": "There is no information about the donor receiving a benefit over a certain limit. The donation is for vet costs, and no benefit is mentioned. However, the scenario does not establish whether any such benefit exists, so the proposition cannot be confirmed.",
      "status": "UNKNOWN"
    },
    {
      "evidence_quote": "",
      "id": "a7",
      "justification": "The donation is not described as a payment of shares. The scenario specifies it is a personal bank account transfer for vet costs, not a share payment.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "",
      "id": "a8",
      "justification": "The donation is not from a charity card or voucher. The scenario explicitly states it was made from a personal bank account and not via charity card or voucher.",
      "status": "TRUE"
    }
  ]
}
